// checkout-form.test.tsx — an integration test: real component tree, mocked network, user-level assertions.
import { describe, expect, test, beforeAll, afterAll, afterEach } from 'vitest';
import { render, screen } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { http, HttpResponse } from 'msw';
import { setupServer } from 'msw/node';
import { CheckoutForm } from './checkout-form';

const server = setupServer(
  http.post('/api/orders', async ({ request }) => {
    const body = (await request.json()) as { email: string; qty: number };
    return HttpResponse.json({ id: 'ord_123', email: body.email, qty: body.qty }, { status: 201 });
  }),
);

beforeAll(() => server.listen({ onUnhandledRequest: 'error' })); // unexpected requests fail loudly
afterEach(() => server.resetHandlers());
afterAll(() => server.close());

describe('CheckoutForm', () => {
  test('places an order and shows a confirmation', async () => {
    const user = userEvent.setup();
    render(<CheckoutForm />);

    await user.type(screen.getByLabelText(/email/i), 'ada@example.com');
    await user.clear(screen.getByRole('spinbutton', { name: /quantity/i }));
    await user.type(screen.getByRole('spinbutton', { name: /quantity/i }), '2');
    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(await screen.findByRole('status')).toHaveTextContent(/order ord_123 confirmed/i);
    expect(screen.queryByRole('alert')).not.toBeInTheDocument();
  });

  test('shows a server error without losing input', async () => {
    server.use(http.post('/api/orders', () => HttpResponse.json({ error: 'Out of stock' }, { status: 409 })));
    const user = userEvent.setup();
    render(<CheckoutForm />);

    await user.type(screen.getByLabelText(/email/i), 'ada@example.com');
    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(await screen.findByRole('alert')).toHaveTextContent(/out of stock/i);
    expect(screen.getByLabelText(/email/i)).toHaveValue('ada@example.com');
  });

  test('validates email before sending', async () => {
    const user = userEvent.setup();
    render(<CheckoutForm />);
    await user.click(screen.getByRole('button', { name: /place order/i }));
    expect(screen.getByLabelText(/email/i)).toHaveAccessibleDescription(/enter a valid email/i);
  });
});

