test('buyer can check out a product', async ({ page, request }) => {
  const res = await request.post('/api/test/seed-product', { data: { stock: 3 } }); // isolated data per test
  const { slug } = (await res.json()) as { slug: string };

  await page.goto(`/products/${slug}`);
  await page.getByRole('button', { name: 'Add to cart' }).click();
  await expect(page.getByRole('status')).toHaveText('1 item in cart'); // retries until true or timeout

  await page.getByRole('link', { name: 'Cart' }).click();
  await page.getByRole('button', { name: 'Checkout' }).click();
  await expect(page).toHaveURL(/\/orders\/ord_/);
  await expect(page.getByRole('heading', { name: 'Thank you' })).toBeVisible();

  await expect(page.getByRole('main')).toHaveScreenshot('order-confirmation.png', {
    mask: [page.getByTestId('order-date')], // dynamic content would make the diff flaky
    maxDiffPixelRatio: 0.01,
  });
});

// Accessible tabs (APG pattern) with roving tabindex, plus an accessible form error pattern.
'use client';
import { useId, useRef, useState, type KeyboardEvent } from 'react';

type TabDef = { id: string; label: string; content: React.ReactNode };

export function Tabs({ tabs, label }: { tabs: TabDef[]; label: string }) {
  const [active, setActive] = useState(0);
  const refs = useRef<(HTMLButtonElement | null)[]>([]);
  const base = useId();

  function onKeyDown(e: KeyboardEvent<HTMLButtonElement>, index: number) {
    const last = tabs.length - 1;
    const next =
      e.key === 'ArrowRight' ? (index === last ? 0 : index + 1)
      : e.key === 'ArrowLeft' ? (index === 0 ? last : index - 1)
      : e.key === 'Home' ? 0
      : e.key === 'End' ? last
      : null;
    if (next === null) return;
    e.preventDefault();
    setActive(next); // automatic activation; manual activation would wait for Enter/Space
    refs.current[next]?.focus();
  }

  return (
    <div>
      <div role="tablist" aria-label={label}>
        {tabs.map((t, i) => (
          <button
            key={t.id}
            ref={(el) => { refs.current[i] = el; }}
            role="tab"
            id={`${base}-tab-${t.id}`}
            aria-selected={i === active}
            aria-controls={`${base}-panel-${t.id}`}
            tabIndex={i === active ? 0 : -1} // roving tabindex: one tab stop for the whole tablist
            onClick={() => setActive(i)}
            onKeyDown={(e) => onKeyDown(e, i)}
          >
            {t.label}
          </button>
        ))}
      </div>
      {tabs.map((t, i) => (
        <div
          key={t.id}
          role="tabpanel"
          id={`${base}-panel-${t.id}`}
          aria-labelledby={`${base}-tab-${t.id}`}
          hidden={i !== active}
          tabIndex={0}
        >
          {t.content}
        </div>
      ))}
    </div>
  );
}

export function EmailField({ error }: { error?: string }) {
  const id = useId();
  return (
    <div>
      <label htmlFor={id}>Email</label>
      <p id={`${id}-hint`}>We will send the receipt here.</p>
      <input
        id={id}
        type="email"
        autoComplete="email"
        required
        aria-invalid={error ? true : undefined}
        aria-describedby={error ? `${id}-hint ${id}-error` : `${id}-hint`}
      />
      {error && <p id={`${id}-error`}>Error: {error}</p>}
    </div>
  );
}

// A polite live region that exists before its text changes.
export function SaveStatus({ message }: { message: string }) {
  return (
    <p role="status" className="sr-only">
      {message}
    </p>
  );
}

// Safe rendering helpers: URL scheme checks, sanitised HTML via a Trusted Types policy, and a nonce-based CSP in proxy.ts.
import DOMPurify from 'dompurify';

export function safeHref(input: string): string | undefined {
  try {
    const url = new URL(input, 'https://placeholder.invalid'); // relative URLs resolve against a dummy base
    return url.protocol === 'https:' || url.protocol === 'http:' ? input : undefined; // blocks javascript:, data:
  } catch {
    return undefined;
  }
}

type TTPolicy = { createHTML: (s: string) => unknown };
type TTFactory = { createPolicy: (name: string, rules: { createHTML: (s: string) => string }) => TTPolicy };
const tt = (globalThis as { trustedTypes?: TTFactory }).trustedTypes;

const policy: TTPolicy = tt
  ? tt.createPolicy('app-sanitize', {
      createHTML: (s) => DOMPurify.sanitize(s, { USE_PROFILES: { html: true }, FORBID_TAGS: ['style', 'form'] }),
    })
  : { createHTML: (s) => DOMPurify.sanitize(s, { USE_PROFILES: { html: true } }) }; // same sanitising without TT support

export function setUserHtml(el: Element, html: string): void {
  el.innerHTML = policy.createHTML(html) as string; // TrustedHTML where enforced; sanitised string elsewhere
}

