// Server-side guards a frontend team often owns in a BFF or route handler: CSRF via Fetch Metadata and Origin, strict CORS.
const APP_ORIGIN = 'https://app.example.com';
const CORS_ALLOWED = new Set(['https://app.example.com', 'https://admin.example.com']); // exact matches only

const SAFE_METHODS = new Set(['GET', 'HEAD', 'OPTIONS']);

export function rejectCrossSiteWrites(req: Request): Response | null {
  if (SAFE_METHODS.has(req.method)) return null; // GET must never change state
  const site = req.headers.get('sec-fetch-site'); // same-origin | same-site | cross-site | none
  if (site === 'cross-site') return new Response('Forbidden', { status: 403 });
  const origin = req.headers.get('origin');
  if (origin && origin !== APP_ORIGIN) return new Response('Forbidden', { status: 403 });
  return null;
}

export function corsHeaders(req: Request): Headers {
  const h = new Headers({ Vary: 'Origin' }); // caches must key on Origin when the header is dynamic
  const origin = req.headers.get('origin');
  if (origin && CORS_ALLOWED.has(origin)) {
    h.set('Access-Control-Allow-Origin', origin); // never "*" with credentials, never a blind reflection
    h.set('Access-Control-Allow-Credentials', 'true');
    h.set('Access-Control-Allow-Methods', 'GET, POST, PUT, DELETE');
    h.set('Access-Control-Allow-Headers', 'Content-Type, X-Request-Id');
    h.set('Access-Control-Max-Age', '600');
  }
  return h;
}

export const sessionCookie = (value: string) =>
  `__Host-session=${value}; Path=/; Secure; HttpOnly; SameSite=Lax; Max-Age=${60 * 60 * 8}`;

export const securityHeaders: Record<string, string> = {
  'Strict-Transport-Security': 'max-age=63072000; includeSubDomains; preload',
  'X-Content-Type-Options': 'nosniff',
  'Referrer-Policy': 'strict-origin-when-cross-origin',
  'Permissions-Policy': 'camera=(), microphone=(), geolocation=()',
  'X-Frame-Options': 'DENY', // legacy; CSP frame-ancestors 'none' is the modern equivalent
};

// postMessage: verify the sender before trusting data.
export function listenForCheckoutMessages(onPaid: (orderId: string) => void): () => void {
  const handler = (e: MessageEvent) => {
    if (e.origin !== 'https://pay.example.com') return;
    const data = e.data as { type?: string; orderId?: unknown };
    if (data?.type === 'paid' && typeof data.orderId === 'string') onPaid(data.orderId);
  };
  window.addEventListener('message', handler);
  return () => window.removeEventListener('message', handler);
}
